// Check if the interval is valid
if (a >= b) {
    return std::numeric_limits<double>::quiet_NaN();
}

// Evaluate function at endpoints
double fa = f(a);
double fb = f(b);

// Check if root is at endpoints
if (std::abs(fa) < precision) return a;
if (std::abs(fb) < precision) return b;

// Check if signs are different (intermediate value theorem)
if (fa * fb > 0) {
    return std::numeric_limits<double>::quiet_NaN();
}

double c = a;
for (unsigned int i = 0; i < max_iter; ++i) {
    c = (a + b) / 2.0;
    double fc = f(c);

    if (std::abs(fc) < precision || (b - a) / 2.0 < precision) {
        return c;
    }

    if (fa * fc < 0) {
        b = c;
        fb = fc;
    } else {
        a = c;
        fa = fc;
    }
}

return c;

